code.java:
Stack<Character> stack = new Stack<>();
for (char c : s.toCharArray()) {
    if (c == '(') stack.push(')');
    else if (c == '{') stack.push('}');
    else if (c == '[') stack.push(']');
    else if (stack.isEmpty() || stack.pop() != c) return false;
}
return stack.isEmpty();

code.cpp:
std::stack<char> st;
for (char c : s) {
    if (c == '(' || c == '{' || c == '[') st.push(c);
    else {
        if (st.empty()) return false;
        if (c == ')' && st.top() != '(') return false;
        if (c == '}' && st.top() != '{') return false;
        if (c == ']' && st.top() != '[') return false;
        st.pop();
    }
}
return st.empty();
